      "path": "lib/index.js",
      "content": "/**\n * dsh-lighthouse —— 宿主入口。\n *\n * 一句话：**一屏看清你发出去的每个作品现在怎么样了** —— 本地拿什么版本、GitHub 有没有动静、\n * 市场收没收录、被下载多少次、还给收录 PR 等了多久（对比上游中位数）。\n *\n * 它只读：不发任何写请求，不动你的仓库，也不生成任何\"看起来像\"的数字 —— 要么来自 API，要么标\"读不到\"。\n *\n * @module dsh-lighthouse\n */\n\nimport { readFile, writeFile } from 'node:fs/promises';\nimport { homedir } from 'node:os';\nimport { join } from 'node:path';\nimport { collectAll } from './collect.js';\nimport { STATUS_ROUTE, createStatusHandler } from './status-route.js';\nimport { defaultFleetPath, parseLoose, readFleet, validateFleet, writeFleet } from './fleet.js';\nimport { renderText, writeReport } from './render.js';\n\n/** 插件身份。 */\nexport const name = 'dsh-lighthouse';\n\n/** 需要宿主提供的服务（拿不到就退化，不报错）。 */\nexport const inject = ['tools', 'systemPrompt'];\n\nconst SECTION_ORDER = 207;\nconst TOOL_TIMEOUT_MS = 180000;\n\n/** 面向模型的公告（常驻那一段）。 */\nexport const LIGHTHOUSE_GUIDANCE = [\n  '本机已安装 **dsh-lighthouse（灯塔）**：`lighthouse_report` 一屏汇总每个作品的现状（本地版本/文件数、GitHub star 与最后推送、市场**是否已收录/下载量/同类排名**、收录 PR 等了多久对比上游中位数），并落一张**可直接截图**的 HTML 卡片。',\n  '它**只读**：所有请求都是 GET；读不到就标\"读不到\"，绝不编数字。',\n  '名册（照谁看）是一份**显式文件**，默认 `~/.dsh/lighthouse-fleet.json`；`lighthouse_fleet` 可以 show/init 它 —— **名册不自动发现**（不许从目录名猜哪些是你的作品）。',\n  '典型用法：想知道\"我们的插件上市场了吗 / 有人装吗\"→ 调 `lighthouse_report`；卡片路径会随结果返回，可直接给用户看。',\n].join('\\n');\n\n/** 动态取 defineTool：宿主里有就用真的，单测/CLI 场景退化成恒等。 */\nlet defineTool = (def) => def;\ntry {\n  const mod = await import('@deepseek-ai/dsh-tools');\n  if (mod && typeof mod.defineTool === 'function') defineTool = mod.defineTool;\n} catch {\n  /* 宿主外运行 */\n}\n\n/**\n * 找 PAT（跟滑道同一套顺序）。\n * @param {string} [explicit] 显式路径\n * @returns {Promise<string|null>} token\n */\nexport async function resolveToken(explicit) {\n  const candidates = [];\n  if (typeof explicit === 'string' && explicit !== '') candidates.push(explicit);\n  if (typeof process.env.DSH_SLIPWAY_TOKEN_FILE === 'string' && process.env.DSH_SLIPWAY_TOKEN_FILE !== '') {\n    candidates.push(process.env.DSH_SLIPWAY_TOKEN_FILE);\n  }\n  candidates.push(join(homedir(), '.dsh', '.gh-token'));\n  candidates.push('D:\\\\dsh\\\\.gh-token');\n  for (const file of candidates) {\n    try {\n      const text = await readFile(file, 'utf8');\n      const token = text.trim();\n      if (token !== '') return token;\n    } catch {\n      /* 换下一个 */\n    }\n  }\n  return null;\n}\n\n/**\n * 默认市场地址。\n *\n * 市场登记表的路由（`/dsh-market/registry`）挂在**宿主自己的 web 服务**上，\n * 所以默认地址必须问 webServer 要 origin —— 写死端口（比如 19387）迟早会失联，\n * 那时报告只会显示\"读不到\"，而人容易把它误读成\"没人用\"。\n *\n * @param {object} [ctx] 宿主上下文（CLI 场景没有）\n * @returns {string} 市场接口根地址\n */\nexport function defaultMarketUrl(ctx) {\n  try {\n    const web = typeof ctx?.get === 'function' ? ctx.get('webServer') : undefined;\n    const origin = typeof web?.getOrigin === 'function' ? web.getOrigin() : '';\n    if (typeof origin === 'string' && origin.trim() !== '') return origin.trim();\n  } catch {\n    /* 没有 webServer：退回环境变量/旧默认 */\n  }\n  return process.env.DSH_WEB_URL ?? 'http://127.0.0.1:19387';\n}\n\n/** 默认卡片目录。 */\nexport function defaultReportDir() {\n  return join(homedir(), '.dsh', 'lighthouse-reports');\n}\n\n/**\n * 跑一次报告（工具与 CLI 共用）。\n * @param {object} input 参数\n * @returns {Promise<object>} `{ ok, report, htmlPath, jsonPath, errors }`\n */\nexport async function runReport(input = {}, ctx = undefined) {\n  const fleetPath = input.fleetFile ?? defaultFleetPath();\n  const read = await readFleet(fleetPath);\n  if (read.ok !== true) return { ok: false, errors: read.errors, fleetPath };\n\n  const token = await resolveToken(input.tokenFile);\n  const report = await collectAll(read.fleet, {\n    token,\n    marketUrl: input.marketUrl ?? defaultMarketUrl(ctx),\n    includeNpm: input.includeNpm !== false,\n  });\n  report.tokenFound = token !== null;\n\n  let paths = { htmlPath: null, jsonPath: null };\n  if (input.writeFiles !== false) {\n    paths = await writeReport(report, {\n      dir: input.reportDir ?? defaultReportDir(),\n      html: input.html !== false,\n      json: input.json === true,\n    });\n  }\n  return { ok: true, report, ...paths, fleetPath };\n}\n\n/**\n * 挂载插件。\n * @param {import('@deepseek-ai/cordis').Context} ctx 宿主上下文\n * @param {object} [config] 插件配置\n */\nexport function apply(ctx, config) {\n  const cfg = config ?? {};\n  if (cfg.enabled === false) return;\n  const disposers = [];\n\n  if (ctx.tools !== undefined && typeof ctx.tools.register === 'function') {\n    disposers.push(ctx.tools.register(defineTool({\n      name: 'lighthouse_report',\n      description: [\n        '一屏看清每个作品的现状：本地（版本/文件数/有无自测）、GitHub（star/fork/最后推送）、市场（**是否已收录、下载量、同类排名**）、收录 PR（等了多少 vs 上游中位数），并落一张可截图的 HTML 卡片。',\n        '**只读**：全部是 GET 请求；某个数据源读不到就标\"读不到\"，不会编数字。',\n        '名册（要看守哪些作品）来自 `~/.dsh/lighthouse-fleet.json`，可用 fleetFile 指到别处。',\n      ].join('\\n'),\n      timeoutMs: TOOL_TIMEOUT_MS,\n      parameters: {\n        fleetFile: { type: 'string', description: '名册文件路径（默认 ~/.dsh/lighthouse-fleet.json）' },\n        reportDir: { type: 'string', description: '卡片落盘目录（默认 ~/.dsh/lighthouse-reports）' },\n        html: { type: 'boolean', description: '是否落 HTML 卡片（默认 true）' },\n        includeNpm: { type: 'boolean', description: '是否顺手查 npm（默认 true）' },\n        marketUrl: { type: 'string', description: `市场接口根地址（默认取宿主 web 服务的 origin，即 ${defaultMarketUrl()}）` },\n        tokenFile: { type: 'string', description: 'PAT 文件路径（不填则按 env / ~/.dsh / D:\\\\dsh 依次找）' },\n      },\n      output: {\n        schema: {\n          type: 'object',\n          additionalProperties: false,\n          properties: {\n            ok: { type: 'boolean', required: true },\n            data: { type: 'json' },\n            error: { type: 'string' },\n          },\n        },\n        render: (_args, value) => {\n          if (value.ok === false && value.data === undefined) {\n            return [{ type: 'text', text: `lighthouse_report 失败：${String(value.error ?? '未知错误')}` }];\n          }\n          const d = value.data ?? {};\n          if (d.ok === false) {\n            return [{ type: 'text', text: `lighthouse_report 失败：\\n  ${(d.errors ?? []).join('\\n  ')}\\n  （名册：${d.fleetPath ?? '?'}）` }];\n          }\n          const lines = [renderText(d.report)];\n          if (d.htmlPath) lines.push(`  卡片已落盘：${d.htmlPath}`);\n          if (d.report?.tokenFound === false) lines.push('  ⚠️ 没找到 PAT：GitHub 部分可能只有公开信息或读不到');\n          return [{ type: 'text', text: lines.join('\\n') }];\n        },\n      },\n      async execute(args) {\n        try {\n          const data = await runReport({\n            fleetFile: args?.fleetFile ?? cfg.fleetFile,\n            reportDir: args?.reportDir ?? cfg.reportDir,\n            html: args?.html,\n            includeNpm: args?.includeNpm,\n            marketUrl: args?.marketUrl ?? cfg.marketUrl,\n            tokenFile: args?.tokenFile ?? cfg.tokenFile,\n          }, ctx);\n          // **不能**写 `error: undefined`：宿主用 lossless-JSON 校验返回对象，\n          // JSON.stringify 会悄悄丢掉 undefined，校验器不会 —— 会被判 \"invalid output\"。\n          const out = { ok: data.ok === true, data };\n          if (out.ok !== true) out.error = String((data.errors ?? [])[0] ?? '未完成');\n          return out;\n        } catch (err) {\n          return { ok: false, error: err instanceof Error ? err.message : String(err) };\n        }\n      },\n    })));\n\n    disposers.push(ctx.tools.register(defineTool({\n      name: 'lighthouse_fleet',\n      description: [\n        '看/写灯塔的**名册**（它照着名册看，不自动发现作品）。',\n        \"action='show'：显示名册路径与它看守的作品。\",\n        \"action='sync'：拿每个作品本地 package.json 的 `dsh.displayName` / `repository` 回填名册里**空着**的中文名与直达链接，并报告「名册包名与仓库对不上」的情况（只报告，不擅自改名）。滑道发布过（尤其改名）之后跑一次，灯塔就跟上了。\",\n        \"action='init'：用显式给的 owner 与 works 建名册 —— works 是 JSON 数组字符串，每条形如 {\\\\\\\"name\\\\\\\":\\\\\\\"dsh-slipway\\\\\\\",\\\\\\\"repo\\\\\\\":\\\\\\\"dsh-slipway\\\\\\\",\\\\\\\"category\\\\\\\":\\\\\\\"tools\\\\\\\",\\\\\\\"localDir\\\\\\\":\\\\\\\"D:\\\\\\\\dsh\\\\\\\\projects\\\\\\\\dsh-slipway\\\\\\\"}；**必须显式给，不猜**。\",\n      ].join('\\n'),\n      timeoutMs: 30000,\n      parameters: {\n        action: { type: 'string', description: 'show | sync（回填中文名/链接并报告对不上的） | init' },\n        fleetFile: { type: 'string', description: '名册文件路径（默认 ~/.dsh/lighthouse-fleet.json）' },\n        owner: { type: 'string', description: 'init 用：GitHub 账号' },\n        works: { type: 'string', description: 'init 用：works 的 JSON 数组字符串' },\n        upstreamOwner: { type: 'string', description: 'init 用：上游收录仓库 owner（默认 awesome-dsh-plugin）' },\n        upstreamRepo: { type: 'string', description: 'init 用：上游收录仓库名（默认 awesome-dsh-plugin）' },\n      },\n      output: {\n        schema: {\n          type: 'object',\n          additionalProperties: false,\n          properties: {\n            ok: { type: 'boolean', required: true },\n            data: { type: 'json' },\n            error: { type: 'string' },\n          },\n        },\n        render: (_args, value) => {\n          if (value.ok !== true) return [{ type: 'text', text: `lighthouse_fleet 失败：${String(value.error ?? '未知错误')}` }];\n          const d = value.data ?? {};\n          if (d.action === 'init') {\n            return [{ type: 'text', text: `名册已写入：${d.fleetPath}\\n  · owner：${d.owner}\\n  · 看守 ${d.count} 个作品：${(d.names ?? []).join(', ')}` }];\n          }\n          if (d.action === 'sync') {\n            const fixed = Array.isArray(d.updated) ? d.updated : [];\n            const bad = Array.isArray(d.mismatched) ? d.mismatched : [];\n            const lines = [`名册已同步：${d.fleetPath}（${d.count} 个作品）`];\n            if (fixed.length > 0) lines.push(`  · 回填：${fixed.join('；')}`);\n            else lines.push('  · 没有需要回填的空字段');\n            if (bad.length > 0) lines.push(`  · ⚠ 对不上：${bad.map((x) => `${x.name} —— ${x.problem}`).join('；')}`);\n            return [{ type: 'text', text: lines.join('\\n') }];\n          }\n          return [{\n            type: 'text',\n            text: `名册：${d.fleetPath}\\n  · owner：${d.owner ?? '(缺)'}\\n  · ${d.count} 个作品：${(d.names ?? []).join(', ')}\\n  · 上游：${d.upstream ?? '?'}${d.error ? `\\n  · 读名册出错：${d.error}` : ''}`,\n          }];\n        },\n      },\n      async execute(args) {\n        const a = args ?? {};\n        const action = String(a.action ?? 'show').toLowerCase();\n        const fleetPath = a.fleetFile ?? cfg.fleetFile ?? defaultFleetPath();\n        try {\n          if (action === 'init') {\n            let works;\n            try {\n              works = JSON.parse(String(a.works ?? ''));\n            } catch {\n              return { ok: false, error: 'works 不是合法 JSON 数组字符串' };\n            }\n            const checked = validateFleet({\n              owner: a.owner,\n              upstream: { owner: a.upstreamOwner, repo: a.upstreamRepo },\n              works,\n            });\n            if (checked.ok !== true) return { ok: false, error: checked.errors.join('；') };\n            await writeFleet(fleetPath, checked.fleet);\n            return {\n              ok: true,\n              data: { action: 'init', fleetPath, owner: checked.fleet.owner, count: checked.fleet.works.length, names: checked.fleet.works.map((w) => w.name) },\n            };\n          }\n          const read = await readFleet(fleetPath);\n          const fleet = read.fleet;\n          if (action === 'sync') {\n            // 拿本地 package.json 回填 nameZh / url，并报告\"名册与仓库对不上\"的情况。\n            // 只补**空**字段（不覆盖你手写的），对不上的只报告、不擅自改 name/repo。\n            if (read.ok !== true) return { ok: false, error: read.errors.join('；') };\n            const fixed = [];\n            const mismatched = [];\n            const next = JSON.parse(JSON.stringify(fleet));\n            for (const work of next.works) {\n              if (work.localDir === null) continue;\n              let manifest = null;\n              try {\n                const text = await readFile(join(work.localDir, 'package.json'), 'utf8');\n                manifest = parseLoose(text);\n              } catch {\n                mismatched.push({ name: work.name, problem: `读不到 ${work.localDir}\\\\package.json` });\n                continue;\n              }\n              if (manifest.name && manifest.name !== work.name) {\n                mismatched.push({ name: work.name, problem: `包名是 ${manifest.name}（名册写的 ${work.name}）` });\n              }\n              if (!work.nameZh && typeof manifest?.dsh?.displayName === 'string' && manifest.dsh.displayName !== '') {\n                work.nameZh = manifest.dsh.displayName;\n                fixed.push(`${work.name} 补中文名「${work.nameZh}」`);\n              }\n              if (!work.url) {\n                const repo = manifest.repository?.url ?? manifest.homepage ?? null;\n                if (typeof repo === 'string' && repo !== '') {\n                  work.url = repo.replace(/^git\\+/, '').replace(/\\.git$/, '');\n                  fixed.push(`${work.name} 补链接 ${work.url}`);\n                }\n              }\n            }\n            if (fixed.length > 0) await writeFleet(fleetPath, next);\n            return {\n              ok: true,\n              data: {\n                action: 'sync',\n                fleetPath,\n                updated: fixed,\n                mismatched,\n                count: next.works.length,\n              },\n            };\n          }\n          return {\n            ok: true,\n            data: {\n              action: 'show',\n              fleetPath,\n              owner: fleet?.owner ?? null,\n              count: fleet?.works?.length ?? 0,\n              names: (fleet?.works ?? []).map((w) => w.name),\n              upstream: fleet ? `${fleet.upstream.owner}/${fleet.upstream.repo}@${fleet.upstream.branch}` : null,\n              error: read.ok === true ? null : read.errors.join('；'),\n            },\n          };\n        } catch (err) {\n          return { ok: false, error: err instanceof Error ? err.message : String(err) };\n        }\n      },\n    })));\n  }\n\n  // —— 界面「作品观察区」的数据口：GET /dsh-lighthouse/status（只读，与工具同一条采集路径）\n  //\n  // 必须用 `ctx.inject([...], host => ...)` 等 webServer 就位再注册（官方插件也是这么写的）。\n  // 实测教训：写成 `ctx.get('webServer')` 时，apply 那一刻服务还没挂上 → 拿到 undefined →\n  // 整段被跳过 → 界面读数据 404，而插件其它能力一切正常 —— \"只少一块\"最难查。\n  try {\n    if (typeof ctx.inject === 'function') {\n      ctx.inject(['webServer'], (host) => {\n        host.effect(() => host.webServer.register({\n          kind: 'exact',\n          path: STATUS_ROUTE,\n          handler: createStatusHandler({\n            fleetFile: cfg.fleetFile ?? defaultFleetPath(),\n            marketUrl: cfg.marketUrl ?? defaultMarketUrl(host),\n            // 延迟解析：注册路由时还没有 token，第一次请求时再拿。\n            // 注意：`resolveToken` 返回的**就是字符串**（不是 { token, from } 那种对象）——\n            // 写成 `.then((found) => found.token)` 会拿到 undefined，于是整条口子**静默退化成匿名请求**；\n            // 实测后果：匿名额度 60/小时一用完，7 个仓库全 403，面板上一片\"读不到仓库\"。\n            token: () => resolveToken(cfg.tokenFile),\n          }),\n        }, 'dsh-lighthouse: status route'));\n      });\n    }\n  } catch {\n    /* 没有 web server 的表面（例如纯 CLI）：观察区缺席，其它能力不受影响 */\n  }\n\n  if (cfg.announceToAgent === true && ctx.systemPrompt !== undefined\n    && typeof ctx.systemPrompt.section === 'function') {\n    disposers.push(ctx.systemPrompt.section({\n      name: 'plugin:lighthouse',\n      order: SECTION_ORDER,\n      text: LIGHTHOUSE_GUIDANCE,\n    }));\n  }\n\n  if (typeof ctx.effect === 'function' && disposers.length > 0) {\n    ctx.effect(() => () => {\n      for (const dispose of disposers) {\n        try {\n          if (typeof dispose === 'function') dispose();\n        } catch {\n          /* 卸载失败不阻断其它清理 */\n        }\n      }\n    }, 'dsh-lighthouse: teardown');\n  }\n}\n\n/** 供 CLI 复用的写文件工具（保证 CLI 与工具用同一套名册格式）。 */\nexport { writeFile };\n"
    },
    {
      "path": "lib/collect.js",
      "content": "/**\n * dsh-lighthouse · collect —— 去三个地方把事实取回来：本地工程、GitHub、插件市场。\n *\n * 纪律：\n *   - **只读**：本模块一个写请求都不发（全是 GET）；\n *   - **可注入 fetch**：测试用假通道，不碰网络；\n *   - **失败不炸**：单个数据源挂了就记 `error`，其余照常出结果 —— 看板缺一格好过整块黑屏；\n *   - **registry 只拉一次**：那份 JSON 有 5MB 上下，**绝不按作品重复打接口**（第一版犯过）。\n *\n * @module dsh-lighthouse/collect\n */\n\nimport { readFile, readdir, stat } from 'node:fs/promises';\nimport { join } from 'node:path';\nimport { parseLoose } from './fleet.js';\n\n/** 市场接口默认地址（本机 DSH Web）。 */\nexport const DEFAULT_MARKET_URL = 'http://127.0.0.1:19387';\n\n/** 收集文件时跳过的目录。 */\nconst SKIP_DIRS = new Set(['.git', 'node_modules', '.github', 'coverage', '.cache']);\n\n/** 递归数文件（用于\"本地有多少东西\"）。 */\nasync function countFiles(dir) {\n  let total = 0;\n  let entries;\n  try {\n    entries = await readdir(dir, { withFileTypes: true });\n  } catch {\n    return 0;\n  }\n  for (const entry of entries) {\n    if (SKIP_DIRS.has(entry.name)) continue;\n    const full = join(dir, entry.name);\n    let st;\n    try {\n      st = await stat(full);\n    } catch {\n      continue;\n    }\n    if (st.isDirectory()) total += await countFiles(full);\n    else if (st.isFile()) total += 1;\n  }\n  return total;\n}\n\n/**\n * 本地：读工程的 package.json 与测试文件是否存在。\n * @param {object} work 名册条目\n * @returns {Promise<object>} 本地事实\n */\nexport async function collectLocal(work) {\n  if (work.localDir === null) return { available: false, reason: '名册里没有 localDir' };\n  const dir = work.localDir;\n  const out = { available: true, dir };\n  try {\n    const text = await readFile(join(dir, 'package.json'), 'utf8');\n    const manifest = parseLoose(text);\n    out.name = manifest.name ?? null;\n    out.version = manifest.version ?? null;\n    out.compatible = Object.keys(manifest?.dsh?.compatibility?.dshReleases ?? {});\n    // 中文显示名：优先 dsh.displayName（插件自己声明），也顺手带出 homepage 当直达链接的候选\n    out.displayName = typeof manifest?.dsh?.displayName === 'string' ? manifest.dsh.displayName : null;\n    out.homepage = typeof manifest.homepage === 'string' ? manifest.homepage : null;\n  } catch (err) {\n    out.available = false;\n    out.reason = `读不到 package.json：${err instanceof Error ? err.message : String(err)}`;\n    return out;\n  }\n  out.files = await countFiles(dir);\n  try {\n    const st = await stat(join(dir, 'test', 'smoke.mjs'));\n    out.hasSmoke = st.isFile();\n  } catch {\n    out.hasSmoke = false;\n  }\n  return out;\n}\n\n/**\n * 发一次 GET（不写任何东西）。\n * @param {string} url 地址\n * @param {object} headers 头\n * @param {Function} fetchImpl fetch\n * @returns {Promise<{status:number, json:any}>} 响应\n */\nasync function getJson(url, headers, fetchImpl) {\n  const res = await fetchImpl(url, { method: 'GET', headers });\n  let json = null;\n  try {\n    const text = await res.text();\n    json = text === '' ? null : JSON.parse(text);\n  } catch {\n    json = null;\n  }\n  return { status: res.status, json };\n}\n\n/**\n * GitHub：仓库现状 + 我给它开的 PR。\n * @param {object} work 名册条目\n * @param {object} opts 选项 `{ owner, token, fetchImpl, prIndex }`\n * @returns {Promise<object>} GitHub 事实\n */\nexport async function collectGitHub(work, { owner, token, fetchImpl = fetch, prIndex = null }) {\n  const headers = {\n    Accept: 'application/vnd.github+json',\n    'User-Agent': 'dsh-lighthouse',\n    ...(token ? { Authorization: `Bearer ${token}` } : {}),\n  };\n  const out = { available: false, repo: `${owner}/${work.repo}` };\n  try {\n    const repoRes = await getJson(`https://api.github.com/repos/${owner}/${work.repo}`, headers, fetchImpl);\n    if (repoRes.status === 404) {\n      out.available = true;\n      out.exists = false;\n      return out;\n    }\n    if (repoRes.status !== 200 || repoRes.json === null) {\n      // 403 多半是\"没带 token 走了匿名\"：匿名额度 60/小时，用完就全 403（实测踩过）\n      out.reason = repoRes.status === 403\n        ? '读仓库失败（HTTP 403）：像是没带 token 走了匿名（匿名额度 60/小时）'\n        : `读仓库失败（HTTP ${repoRes.status}）`;\n      return out;\n    }\n    out.available = true;\n    out.exists = true;\n    out.stars = repoRes.json.stargazers_count ?? 0;\n    out.forks = repoRes.json.forks_count ?? 0;\n    // 观察区要的两项：「关注」= watchers（GitHub 的 subscribers_count）；\n    // 「留言」= 开着的 issue/PR 数（open_issues_count 两者都算，够用作\"有没有人说话\"）\n    out.watchers = repoRes.json.subscribers_count ?? 0;\n    out.openIssues = repoRes.json.open_issues_count ?? 0;\n    out.pushedAt = repoRes.json.pushed_at ?? null;\n    out.defaultBranch = repoRes.json.default_branch ?? null;\n  } catch (err) {\n    out.reason = `网络失败：${err instanceof Error ? err.message : String(err)}`;\n    return out;\n  }\n\n  if (Array.isArray(prIndex)) {\n    const needle = `${owner}/${work.repo}`;\n    const mine = prIndex.filter((item) => String(item.title ?? '').includes(needle));\n    out.pr = mine.length > 0\n      ? {\n        number: mine[0].number,\n        state: mine[0].state,\n        title: mine[0].title,\n        createdAt: mine[0].created_at,\n        closedAt: mine[0].closed_at ?? null,\n        mergedAt: mine[0].pull_request?.merged_at ?? null,\n      }\n      : null;\n  }\n  return out;\n}\n\n/**\n * 我开过的全部 PR（一次拉完，给每个作品认领）。失败返回 `[]`。\n * @param {object} opts 选项\n * @returns {Promise<Array>} PR 列表\n */\nexport async function collectMyPulls({ owner, token, fetchImpl = fetch }) {\n  const headers = {\n    Accept: 'application/vnd.github+json',\n    'User-Agent': 'dsh-lighthouse',\n    ...(token ? { Authorization: `Bearer ${token}` } : {}),\n  };\n  try {\n    const res = await getJson(\n      `https://api.github.com/search/issues?q=${encodeURIComponent(`author:${owner} type:pr`)}&per_page=50`,\n      headers,\n      fetchImpl,\n    );\n    return res.status === 200 && Array.isArray(res.json?.items) ? res.json.items : [];\n  } catch {\n    return [];\n  }\n}\n\n/**\n * 把市场登记表拉一次（要同源头，否则被拒 —— 实测）。\n * @param {object} opts 选项\n * @returns {Promise<object>} `{ available, updated, count, list, reason }`\n */\n/** 登记表缓存的默认时长（登记表一天才更新一两次，5 分钟缓存完全够）。 */\nexport const REGISTRY_TTL_MS = 300_000;\n\n/**\n * 登记表缓存：**按 fetchImpl 实例分桶**。\n * 真 fetch 共用一个桶（拿到真实收益），测试自建的假 fetch 各用各的（互不污染）。\n */\nconst registryCache = new WeakMap();\n\nasync function fetchRegistryUncached({ marketUrl, fetchImpl }) {\n  try {\n    const res = await getJson(\n      `${marketUrl}/dsh-market/registry`,\n      { Accept: 'application/json', Origin: marketUrl, Referer: `${marketUrl}/` },\n      fetchImpl,\n    );\n    if (res.status !== 200 || res.json === null) return { available: false, reason: `市场接口 HTTP ${res.status}`, list: [] };\n    const registry = res.json.registry ?? {};\n    const list = Array.isArray(registry.plugins) ? registry.plugins : [];\n    return { available: true, updated: registry.updated ?? null, count: registry.count ?? list.length, list };\n  } catch (err) {\n    return { available: false, reason: `市场接口不可达：${err instanceof Error ? err.message : String(err)}`, list: [] };\n  }\n}\n\n/**\n * 拉市场登记表（带进程内缓存）。\n *\n * 为什么缓存：这份表 **4.4MB**，本地 HTTP 拉一次要 **2.8 秒**（2026-10-17 实测），\n * 而它一天才更新一两次 —— 面板每刷一次都重拉纯属浪费。\n * **只缓存成功结果**：读不到时如实返回，绝不留假数据。\n */\nexport async function fetchRegistry({\n  marketUrl = DEFAULT_MARKET_URL,\n  fetchImpl = fetch,\n  cacheTtlMs = REGISTRY_TTL_MS,\n  now = Date.now,\n} = {}) {\n  let bucket = registryCache.get(fetchImpl);\n  if (bucket === undefined) {\n    bucket = new Map();\n    registryCache.set(fetchImpl, bucket);\n  }\n  const hit = bucket.get(marketUrl);\n  if (hit !== undefined && hit.value.available === true && now() - hit.at < cacheTtlMs) return hit.value;\n  const value = await fetchRegistryUncached({ marketUrl, fetchImpl });\n  bucket.set(marketUrl, { at: now(), value });\n  return value;\n}\n\n/**\n * 从已拉回来的登记表里查一个包（纯函数，不打接口）。\n * @param {object} registry fetchRegistry 的结果\n * @param {string} name 包名\n * @returns {object} 市场事实\n */\nexport function marketFactOf(registry, name) {\n  if (registry?.available !== true) return { available: false, listed: false, reason: registry?.reason ?? '未取到登记表' };\n  const list = registry.list;\n  const hit = list.find((item) => item?.name === name);\n  if (!hit) return { available: true, listed: false, registryUpdated: registry.updated ?? null, registryCount: registry.count ?? list.length };\n  const categories = Array.isArray(hit.category) ? hit.category : [];\n  // 市场的 downloads 只统计发到 npm 的包；没发 npm 的条目字段是缺的（不是 0）。\n  // 把\"没有数据\"当成 0 会把它排到真有包但没人用的后面，也会显示成\"下载 0\"。\n  const toCount = (v) => (v === null || v === undefined || v === '' || Number.isNaN(Number(v)) ? null : Number(v));\n  const downloads = toCount(hit.downloads);\n  const sameCat = list\n    .filter((item) => Array.isArray(item?.category) && categories.some((c) => item.category.includes(c)))\n    .map((item) => toCount(item.downloads))\n    .filter((v) => v !== null)\n    .sort((a, b) => b - a);\n  return {\n    available: true,\n    listed: true,\n    registryUpdated: registry.updated ?? null,\n    registryCount: registry.count ?? list.length,\n    downloads,\n    stars: Number(hit.stars ?? 0),\n    added: hit.added ?? null,\n    category: categories,\n    version: hit.version ?? null,\n    install: hit.install ?? null,\n    marketOwner: hit.owner ?? null,\n    /** 市场条目页（可以点进去看的那个）—— 没收录时没有。 */\n    page: typeof hit.page === 'string' && hit.page !== '' ? hit.page : null,\n    descriptionZh: typeof hit.description?.zh === 'string' ? hit.description.zh : null,\n    rankInCategory: downloads === null ? null : sameCat.indexOf(downloads) + 1,\n    categorySize: sameCat.length,\n  };\n}\n\n/**\n * 便捷版：拉一次登记表再查一个包。\n * @param {string} name 包名\n * @param {object} opts 选项\n * @returns {Promise<object>} 市场事实\n */\nexport async function collectMarket(name, opts = {}) {\n  return marketFactOf(await fetchRegistry(opts), name);\n}\n\n/**\n * 上游节奏：最近一批已合并 PR 等了多久（中位数）—— 用来判断\"我们等得算不算久\"。\n * @param {object} opts 选项 `{ upstream, token, fetchImpl, sample }`\n * @returns {Promise<object>} 上游事实\n */\n/** POST 版 getJson（GraphQL 用）—— 形状与 getJson 一致，测试里的假 fetch 直接可用。 */\nasync function postJson(url, headers, body, fetchImpl) {\n  const res = await fetchImpl(url, { method: 'POST', headers, body: JSON.stringify(body) });\n  let json = null;\n  try {\n    const text = await res.text();\n    json = text === '' ? null : JSON.parse(text);\n  } catch {\n    json = null;\n  }\n  return { status: res.status, json };\n}\n\n/**\n * 用 GraphQL 取上游的合并节奏：**只要两个时间字段**。\n *\n * 为什么值得单独开一条路（2026-10-17 实测）：REST 的\n * `pulls?state=closed&sort=updated&per_page=60` 要 **49 秒** —— 时间全花在传那一大坨\n * PR 对象上（每个 PR 自带几十个字段）；GraphQL 只回 `createdAt/mergedAt`，\n * 100 条只要 **1.3 秒**（快约 38 倍）。这是整条数据口最大的瓶颈。\n *\n * @returns {Promise<{waits:number[], openCount:number|null}|null>} 不可用返回 null（调用方回退 REST）\n */\nasync function upstreamViaGraphQL({ upstream, token, fetchImpl, sample }) {\n  try {\n    const query = 'query($owner:String!,$name:String!,$n:Int!){repository(owner:$owner,name:$name){'\n      + 'merged:pullRequests(last:$n,states:MERGED){nodes{createdAt mergedAt}}'\n      + 'open:pullRequests(states:OPEN){totalCount}}}';\n    const res = await postJson('https://api.github.com/graphql', {\n      Accept: 'application/json',\n      'Content-Type': 'application/json',\n      'User-Agent': 'dsh-lighthouse',\n      Authorization: `Bearer ${token}`,\n    }, {\n      query,\n      variables: { owner: upstream.owner, name: upstream.repo, n: sample },\n    }, fetchImpl);\n    if (res.status !== 200 || res.json === null) return null;\n    const repo = res.json?.data?.repository;\n    const nodes = repo?.merged?.nodes;\n    if (!Array.isArray(nodes)) return null;\n    const waits = nodes\n      .map((node) => (Date.parse(node.mergedAt) - Date.parse(node.createdAt)) / 3600000)\n      .filter((h) => Number.isFinite(h) && h >= 0)\n      .sort((a, b) => a - b);\n    if (waits.length === 0) return null;\n    const openCount = Number.isFinite(repo?.open?.totalCount) ? repo.open.totalCount : null;\n    return { waits, openCount };\n  } catch {\n    return null;\n  }\n}\n\nexport async function collectUpstream({ upstream, token, fetchImpl = fetch, sample = 60 }) {\n  const out = { available: false, upstream: `${upstream.owner}/${upstream.repo}` };\n  const headers = {\n    Accept: 'application/vnd.github+json',\n    'User-Agent': 'dsh-lighthouse',\n    ...(token ? { Authorization: `Bearer ${token}` } : {}),\n  };\n  try {\n    // 先试 GraphQL（快约 38 倍）；不可用（没 token / 形状不对 / 网络问题）再回退 REST\n    let waits = null;\n    if (typeof token === 'string' && token !== '') {\n      const viaGraph = await upstreamViaGraphQL({ upstream, token, fetchImpl, sample });\n      if (viaGraph !== null) {\n        waits = viaGraph.waits;\n        out.openCount = viaGraph.openCount;\n      }\n    }\n    if (waits === null) {\n      const res = await getJson(\n        `https://api.github.com/repos/${upstream.owner}/${upstream.repo}/pulls?state=closed&sort=updated&direction=desc&per_page=${sample}`,\n        headers,\n        fetchImpl,\n      );\n      if (res.status !== 200 || !Array.isArray(res.json)) {\n        out.reason = `读上游 PR 失败（HTTP ${res.status}）`;\n        return out;\n      }\n      waits = res.json\n        .filter((pr) => typeof pr.merged_at === 'string' && pr.merged_at !== '')\n        .map((pr) => (Date.parse(pr.merged_at) - Date.parse(pr.created_at)) / 3600000)\n        .filter((h) => Number.isFinite(h) && h >= 0)\n        .sort((a, b) => a - b);\n      out.openCount = res.json.length;\n    }\n    if (waits.length === 0) {\n      out.reason = '样本里没有已合并的 PR';\n      return out;\n    }\n    out.available = true;\n    out.samples = waits.length;\n    out.medianHours = waits[Math.floor(waits.length / 2)];\n    out.minHours = waits[0];\n    out.maxHours = waits[waits.length - 1];\n    return out;\n  } catch (err) {\n    out.reason = `网络失败：${err instanceof Error ? err.message : String(err)}`;\n    return out;\n  }\n}\n\n/**\n * npm 上有没有这个包（只回答有/没有/查不动）。\n * @param {string} name 包名\n * @param {object} opts 选项\n * @returns {Promise<object>} npm 事实\n */\nexport async function collectNpm(name, { fetchImpl = fetch } = {}) {\n  try {\n    const res = await getJson(`https://registry.npmjs.org/${encodeURIComponent(name)}`, { Accept: 'application/json' }, fetchImpl);\n    if (res.status === 200) return { available: true, published: true, version: res.json?.['dist-tags']?.latest ?? null };\n    if (res.status === 404) return { available: true, published: false };\n    return { available: false, reason: `HTTP ${res.status}` };\n  } catch (err) {\n    return { available: false, reason: err instanceof Error ? err.message : String(err) };\n  }\n}\n\n/** 小时 → 人话。 */\nexport function hoursText(hours) {\n  if (!Number.isFinite(hours)) return '?';\n  if (hours < 1) return `${Math.round(hours * 60)} 分钟`;\n  if (hours < 48) return `${hours.toFixed(1)} 小时`;\n  return `${(hours / 24).toFixed(1)} 天`;\n}\n\n/**\n * 把整份名册跑一遍。\n * @param {object} fleet 名册\n * @param {object} deps 依赖 `{ token, fetchImpl, marketUrl, includeNpm, now }`\n * @returns {Promise<object>} 报告\n */\nexport async function collectAll(fleet, deps = {}) {\n  const { token = null, fetchImpl = fetch, marketUrl = DEFAULT_MARKET_URL, includeNpm = true, now = Date.now() } = deps;\n\n  // 三份\"整表\"各拉一次：登记表（5MB）、我开过的 PR、上游节奏\n  const [registry, prIndex, upstream] = await Promise.all([\n    fetchRegistry({ marketUrl, fetchImpl }),\n    collectMyPulls({ owner: fleet.owner, token, fetchImpl }),\n    collectUpstream({ upstream: fleet.upstream, token, fetchImpl }),\n  ]);\n\n  // 作品之间**必须并发**：串行查 7 个作品时整条口子要 11.6 秒（实测），\n  // 面板上就表现为一段很长的\"读取中\"；并发后总耗时≈最慢的那一个（3~4 秒）。\n  const works = await Promise.all(fleet.works.map(async (work) => {\n    const [local, github, npm] = await Promise.all([\n      collectLocal(work),\n      collectGitHub(work, { owner: fleet.owner, token, fetchImpl, prIndex }),\n      // npm 包名可以和目录/GitHub 仓库名不同（例：仓库 dsh-tool-gate，npm 包 dsh-ctx-gate）。\n      // 名册里给了 work.npm 就用它，否则退回 work.name。\n      includeNpm ? collectNpm(work.npm ?? work.name, { fetchImpl }) : Promise.resolve({ available: false, reason: '已跳过' }),\n    ]);\n    const market = marketFactOf(registry, work.name);\n    // 直达链接：名册显式给的优先；否则 GitHub 仓库；npm 与市场页面能确定才给（不确定就不编）。\n    const links = {\n      github: work.url ?? `https://github.com/${fleet.owner}/${work.repo}`,\n      npm: `https://www.npmjs.com/package/${work.npm ?? work.name}`,\n      market: market.listed === true ? market.page : null,\n    };\n    return { work, local, github, market, npm, links };\n  }));\n\n  const waiting = works\n    .map((w) => w.github.pr)\n    // 用 `!= null` 同时挡 null 与 undefined：prIndex 为空时 collectGitHub 根本不会挂 pr 字段\n    .filter((pr) => pr != null && pr.state === 'open')\n    .map((pr) => (now - Date.parse(pr.createdAt)) / 3600000);\n\n  return {\n    generatedAt: new Date(now).toISOString(),\n    owner: fleet.owner,\n    upstream,\n    market: {\n      url: marketUrl,\n      available: registry.available === true,\n      updated: registry.updated ?? null,\n      count: registry.count ?? null,\n      reason: registry.reason ?? null,\n    },\n    works,\n    summary: {\n      works: works.length,\n      published: works.filter((w) => w.github.exists === true).length,\n      listed: works.filter((w) => w.market?.listed === true).length,\n      totalDownloads: works.reduce((sum, w) => sum + (w.market?.listed === true && w.market.downloads !== null && w.market.downloads !== undefined ? Number(w.market.downloads) : 0), 0),\n      totalStars: works.reduce((sum, w) => sum + Number(w.github.stars ?? 0), 0),\n      openPrs: waiting.length,\n      longestWaitHours: waiting.length > 0 ? Math.max(...waiting) : null,\n    },\n  };\n}\n"
    },
    {
      "path": "lib/status-route.js",
      "content": "/**\n * dsh-lighthouse · status-route —— 给界面观察区供数据的一条**只读**接口。\n *\n * `GET /dsh-lighthouse/status` → `{ ok, report }`（就是 `collectAll` 的那份报告）。\n * 界面那一半（`client.js`）只负责画，不负责算 —— 所以同一个数字在面板、工具、卡片里是一致的。\n *\n * @module dsh-lighthouse/status-route\n */\n\nimport { collectAll } from './collect.js';\nimport { readFleet } from './fleet.js';\n\n/** 观察区取数的路径。 */\nexport const STATUS_ROUTE = '/dsh-lighthouse/status';\n\n/** 统一的 JSON 回包。 */\nfunction send(response, status, payload) {\n  const body = JSON.stringify(payload);\n  response.writeHead(status, {\n    'Content-Type': 'application/json; charset=utf-8',\n    'Cache-Control': 'no-store',\n    'Content-Length': Buffer.byteLength(body),\n  });\n  response.end(body);\n}\n\n/** 本机匿名请求的缓存有效期 —— 免得谁都能借我的 PAT 反复去打 GitHub。 */\nexport const CACHE_TTL_MS = 60_000;\n\n/**\n * 造一个请求处理器。\n * @param {object} options 选项\n * @param {string} options.fleetFile 名册路径\n * @param {string} [options.marketUrl] 市场接口根\n * @param {string|null|Function} [options.token] GitHub PAT（也接受函数：请求时才解析）\n * @param {Function} [options.collect] 采集实现（测试注入）\n * @param {Function} [options.readFleetImpl] 读名册实现（测试注入）\n * @param {Function} [options.now] 取时间（测试注入）\n * @param {number} [options.cacheTtlMs] 匿名来源的缓存时长\n * @returns {Function} `(request, response) => Promise<void>`\n */\nexport function createStatusHandler({\n  fleetFile,\n  marketUrl,\n  token = null,\n  collect = collectAll,\n  readFleetImpl = readFleet,\n  now = Date.now,\n  cacheTtlMs = CACHE_TTL_MS,\n} = {}) {\n  let cache = null; // { at, payload }\n\n  /** 从请求头里取来源（Origin 优先，其次 Referer；都没有就返回 null）。 */\n  function sourceOf(request) {\n    const origin = request?.headers?.origin;\n    if (typeof origin === 'string' && origin !== '') return origin;\n    const referer = request?.headers?.referer;\n    if (typeof referer === 'string' && referer !== '') return referer;\n    return null;\n  }\n\n  /**\n   * 跨源来的请求一律拒掉。\n   *\n   * 背景（实测）：**宿主不为插件注册的路由做认证** —— `webServer.register` 没有 auth 选项，\n   * 宿主根 `/` 要认证（401），插件路由却是裸的。所以准入只能自己加：\n   *   · 带了来源头（界面 fetch 会带 Referer）→ 必须与市场接口同源，否则 403；\n   *   · 没带来源头（curl / 本机脚本）→ 放行。这些信息本来就是公开的（仓库名、star 数），\n   *     真要挡本机进程也挡不住（它直接读工程目录就行），装样子没意义。\n   * 另加一层缓存兜底：界面来的请求**永远实时**（刷新按钮必须真的刷新），\n   * 匿名来源的重复请求 60 秒内吃缓存。\n   */\n  function fromElsewhere(request) {\n    const seen = sourceOf(request);\n    if (seen === null) return false;\n    try {\n      return new URL(seen).origin !== new URL(marketUrl).origin;\n    } catch {\n      return true; // 来源头读不懂：当作别处来的\n    }\n  }\n\n  /** 这次请求是不是界面（同源）来的。 */\n  function fromUi(request) {\n    const seen = sourceOf(request);\n    if (seen === null) return false;\n    try {\n      return new URL(seen).origin === new URL(marketUrl).origin;\n    } catch {\n      return false;\n    }\n  }\n\n  return async function handleStatus(request, response) {\n    const method = String(request?.method ?? 'GET').toUpperCase();\n    if (method !== 'GET' && method !== 'HEAD') {\n      send(response, 405, { ok: false, error: 'method-not-allowed' });\n      return;\n    }\n    if (fromElsewhere(request)) {\n      send(response, 403, { ok: false, error: 'cross-origin-denied' });\n      return;\n    }\n    if (fromUi(request) !== true && cache !== null && now() - cache.at < cacheTtlMs) {\n      send(response, 200, cache.payload);\n      return;\n    }\n    try {\n      const read = await readFleetImpl(fleetFile);\n      if (read.ok !== true) {\n        send(response, 200, { ok: false, errors: read.errors, fleetPath: fleetFile });\n        return;\n      }\n      // token 允许传函数：注册路由时它还没被解析，第一次请求时再拿\n      // （省得为了它把 apply 变成异步 —— 插件加载不该等网络）\n      const resolvedToken = typeof token === 'function' ? await token() : token;\n      // 观察区不查 npm（省一次外网往返），其余与工具走同一条采集路径\n      const report = await collect(read.fleet, { token: resolvedToken, marketUrl, includeNpm: false, now: now() });\n      const payload = { ok: true, report };\n      cache = { at: now(), payload };\n      send(response, 200, payload);\n    } catch (err) {\n      send(response, 500, { ok: false, error: err instanceof Error ? err.message : String(err) });\n    }\n  };\n}\n"
    },
    {
      "path": "lib/fleet.js",
      "content": "/**\n * dsh-lighthouse · fleet —— 舰队名册：灯塔照着这份名册看，不猜。\n *\n * 名册是**显式文件**（默认 `~/.dsh/lighthouse-fleet.json`），形状：\n * ```json\n * {\n *   \"version\": 1,\n *   \"owner\": \"7gzgn\",\n *   \"upstream\": { \"owner\": \"awesome-dsh-plugin\", \"repo\": \"awesome-dsh-plugin\", \"branch\": \"main\" },\n *   \"works\": [\n *     { \"name\": \"dsh-slipway\", \"repo\": \"dsh-slipway\", \"category\": \"tools\", \"localDir\": \"D:\\\\dsh\\\\projects\\\\dsh-slipway\" }\n *   ]\n * }\n * ```\n * 为什么不做\"自动发现\"：**目标必须被明确指认** —— 从目录名或包名前缀去猜\n * \"哪些是你的作品\"，猜错了就会把别人的仓库报进你的看板。\n *\n * @module dsh-lighthouse/fleet\n */\n\nimport { readFile, writeFile, mkdir } from 'node:fs/promises';\nimport { dirname, join } from 'node:path';\n\n/** 名册格式版本。 */\nexport const FLEET_VERSION = 1;\n\n/** 默认名册路径。 */\nexport function defaultFleetPath() {\n  const home = process.env.USERPROFILE ?? process.env.HOME ?? '';\n  return join(home, '.dsh', 'lighthouse-fleet.json');\n}\n\n/** 去掉 BOM 并解析 JSON。 */\nexport function parseLoose(text) {\n  return JSON.parse(String(text).replace(/^\\uFEFF/, ''));\n}\n\n/**\n * 校验名册。**缺 owner 或缺 works 就是错**，不做补全。\n * @param {any} data 名册内容\n * @returns {{ok:boolean, errors:string[], fleet?:object}} 结论\n */\nexport function validateFleet(data) {\n  const errors = [];\n  if (data === null || typeof data !== 'object') {\n    return { ok: false, errors: ['名册不是对象'] };\n  }\n  const owner = data.owner;\n  if (typeof owner !== 'string' || owner.trim() === '') {\n    errors.push('名册缺 owner（GitHub 账号）—— 不猜，必须显式写');\n  }\n  if (!Array.isArray(data.works) || data.works.length === 0) {\n    errors.push('名册的 works 必须是非空数组');\n  } else {\n    data.works.forEach((work, index) => {\n      if (work === null || typeof work !== 'object') {\n        errors.push(`works[${index}] 不是对象`);\n        return;\n      }\n      if (typeof work.name !== 'string' || work.name.trim() === '') errors.push(`works[${index}] 缺 name`);\n      if (typeof work.repo !== 'string' || work.repo.trim() === '') errors.push(`works[${index}] 缺 repo`);\n      if (work.localDir !== undefined && typeof work.localDir !== 'string') errors.push(`works[${index}] 的 localDir 必须是字符串`);\n      if (work.nameZh !== undefined && typeof work.nameZh !== 'string') errors.push(`works[${index}] 的 nameZh 必须是字符串`);\n      if (work.url !== undefined && typeof work.url !== 'string') errors.push(`works[${index}] 的 url 必须是字符串`);\n      if (work.mirrors !== undefined && !Array.isArray(work.mirrors)) errors.push(`works[${index}] 的 mirrors 必须是数组`);\n    });\n  }\n  if (errors.length > 0) return { ok: false, errors };\n  return {\n    ok: true,\n    errors: [],\n    fleet: {\n      version: typeof data.version === 'number' ? data.version : FLEET_VERSION,\n      owner: owner.trim(),\n      upstream: {\n        owner: data.upstream?.owner ?? 'awesome-dsh-plugin',\n        repo: data.upstream?.repo ?? 'awesome-dsh-plugin',\n        branch: data.upstream?.branch ?? 'main',\n      },\n      works: data.works.map((work) => ({\n        name: work.name.trim(),\n        repo: work.repo.trim(),\n        category: typeof work.category === 'string' ? work.category : null,\n        localDir: typeof work.localDir === 'string' && work.localDir !== '' ? work.localDir : null,\n        /** 中文显示名（不填就退回 package.json 的 dsh.displayName，再退回英文名）。 */\n        nameZh: typeof work.nameZh === 'string' && work.nameZh.trim() !== '' ? work.nameZh.trim() : null,\n        /** 直达链接（不填就按 owner/repo 生成 GitHub 地址）。 */\n        url: typeof work.url === 'string' && work.url.trim() !== '' ? work.url.trim() : null,\n        /** npm 包名（仓库名与包名不一定一样，例：仓库 dsh-tool-gate → 包 dsh-ctx-gate）。不填就用 name 查。 */\n        npm: typeof work.npm === 'string' && work.npm.trim() !== '' ? work.npm.trim() : null,\n        /** 额外的发布源（例如 Gitee / GitLab / npm），形如 { platform, url }。 */\n        mirrors: Array.isArray(work.mirrors)\n          ? work.mirrors\n            .filter((m) => m !== null && typeof m === 'object' && typeof m.url === 'string' && m.url !== '')\n            .map((m) => ({ platform: typeof m.platform === 'string' ? m.platform : 'other', url: m.url }))\n          : [],\n      })),\n    },\n  };\n}\n\n/**\n * 读名册。\n * @param {string} file 路径\n * @param {object} [deps] 依赖（测试注入 readFileImpl）\n * @returns {Promise<{ok:boolean, errors:string[], fleet?:object, path:string}>} 结论\n */\nexport async function readFleet(file, deps = {}) {\n  const read = deps.readFileImpl ?? readFile;\n  let text;\n  try {\n    text = await read(file, 'utf8');\n  } catch (err) {\n    return { ok: false, errors: [`名册读不到（${file}）：${err instanceof Error ? err.message : String(err)}`], path: file };\n  }\n  let data;\n  try {\n    data = parseLoose(text);\n  } catch (err) {\n    return { ok: false, errors: [`名册不是合法 JSON：${err instanceof Error ? err.message : String(err)}`], path: file };\n  }\n  const checked = validateFleet(data);\n  return { ...checked, path: file };\n}\n\n/**\n * 写名册（建目录、格式化、带尾换行）。\n * @param {string} file 路径\n * @param {object} fleet 名册\n * @param {object} [deps] 依赖\n * @returns {Promise<string>} 实际写入的路径\n */\nexport async function writeFleet(file, fleet, deps = {}) {\n  const write = deps.writeFileImpl ?? writeFile;\n  const mk = deps.mkdirImpl ?? mkdir;\n  await mk(dirname(file), { recursive: true });\n  await write(file, `${JSON.stringify({ version: FLEET_VERSION, ...fleet }, null, 2)}\\n`, 'utf8');\n  return file;\n}\n"
    },
    {
      "path": "lib/render.js",
      "content": "/**\n * dsh-lighthouse · render —— 把报告渲染成两种东西：给 agent 看的一段话，和给人看的一张卡片。\n *\n * 卡片是**单文件 HTML**：无外链、无脚本依赖、深色、数字大 —— 落盘后可以直接打开、截图发出去。\n *\n * @module dsh-lighthouse/render\n */\n\nimport { mkdir, writeFile } from 'node:fs/promises';\nimport { join } from 'node:path';\nimport { hoursText } from './collect.js';\n\n/** HTML 转义。 */\nfunction esc(text) {\n  return String(text ?? '')\n    .replace(/&/g, '&amp;')\n    .replace(/</g, '&lt;')\n    .replace(/>/g, '&gt;')\n    .replace(/\"/g, '&quot;');\n}\n\n/** ISO 时间 → `MM-DD HH:mm`。 */\nfunction shortTime(iso) {\n  if (typeof iso !== 'string' || iso === '') return '—';\n  const d = new Date(iso);\n  if (Number.isNaN(d.getTime())) return '—';\n  const pad = (n) => String(n).padStart(2, '0');\n  return `${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;\n}\n\n/** 超过这个数量就自动切成紧凑视图（50 个作品时逐张卡片已经读不动了）。 */\nexport const COMPACT_THRESHOLD = 12;\n\n/**\n * 一个作品的\"紧急度\"排序键：**需要人动手的在前**。\n *   0 = 有异常（GitHub/市场读不到、仓库不存在、没有 PR）\n *   1 = 还在等收录（PR open，按等得久的优先）\n *   2 = 已收录\n * @param {object} item 报告里的一项\n * @returns {{tier:number, waitHours:number}} 排序键\n */\nexport function urgencyOf(item) {\n  const { github, market } = item;\n  const pr = github?.pr ?? null;\n  const waitHours = pr?.createdAt ? (Date.now() - Date.parse(pr.createdAt)) / 3600000 : 0;\n  const broken = github?.exists !== true || market?.available !== true || (github?.exists === true && pr === null);\n  if (broken) return { tier: 0, waitHours };\n  if (market?.listed === true) return { tier: 2, waitHours };\n  return { tier: 1, waitHours };\n}\n\n/**\n * 排好序的作品列表：需要盯的在前，同层里等得久的在前。\n * @param {Array<object>} works 报告里的 works\n * @returns {Array<object>} 新数组（不改原对象顺序）\n */\nexport function sortWorks(works) {\n  return [...(Array.isArray(works) ? works : [])]\n    .map((item) => ({ item, key: urgencyOf(item) }))\n    .sort((a, b) => a.key.tier - b.key.tier || b.key.waitHours - a.key.waitHours)\n    .map((entry) => entry.item);\n}\n\n/**\n * 给 agent 的一段话。\n * @param {object} report collectAll 的结果\n * @returns {string} 文本\n */\nexport function renderText(report) {\n  const lines = [];\n  const s = report.summary;\n  const marketReadable = report.market.available === true;\n  lines.push(`作品看板｜${shortTime(report.generatedAt)}｜${report.owner}`);\n  // 市场读不到时**不许显示 0 收录 / 0 下载** —— 那会让人以为\"没人用\"，而事实是\"没读到\"。\n  lines.push(\n    marketReadable\n      ? `  汇总：${s.works} 个作品 · 已发布 ${s.published} · 市场已收录 ${s.listed} · 总下载 ${s.totalDownloads} · 总 star ${s.totalStars} · 待合 PR ${s.openPrs}`\n      : `  汇总：${s.works} 个作品 · 已发布 ${s.published} · **市场数据读不到**（不显示 0，免得被当成没人用） · 总 star ${s.totalStars} · 待合 PR ${s.openPrs}`,\n  );\n  if (marketReadable) {\n    lines.push(`  市场登记表：${report.market.count} 条（更新于 ${String(report.market.updated ?? '?')}）`);\n  } else {\n    lines.push(`  市场登记表：**读不到**（${report.market.reason ?? '未知原因'}）—— 已收录/下载量这几项本次一律不报数`);\n  }\n  if (report.upstream?.available === true) {\n    lines.push(`  上游合并节奏：中位数 ${hoursText(report.upstream.medianHours)}（样本 ${report.upstream.samples} 个已合并 PR）`);\n  } else {\n    lines.push(`  上游合并节奏：**没算出来**（${report.upstream?.reason ?? '未知原因'}）`);\n  }\n\n  // 「等得比上游中位数还久」的 PR 单独点名 —— 这是真正需要盯的一批。\n  if (report.upstream?.available === true) {\n    const median = Number(report.upstream.medianHours);\n    const slow = report.works\n      .map((item) => {\n        const pr = item.github?.pr;\n        if (!pr || pr.state !== 'open' || pr.mergedAt) return null;\n        const hours = (Date.now() - Date.parse(pr.createdAt)) / 3600000;\n        return Number.isFinite(hours) && hours > median ? { name: item.work.name, number: pr.number, hours } : null;\n      })\n      .filter(Boolean)\n      .sort((a, b) => b.hours - a.hours);\n    if (slow.length > 0) {\n      // 作品多了以后这一行会变成一坨 —— 只点名最久的几个，其余报总数（详情在卡片里）。\n      const shown = slow.slice(0, 6);\n      const rest = slow.length - shown.length;\n      lines.push(\n        `  ⏳ 超过上游中位数的 PR ${slow.length} 条：${shown.map((x) => `#${x.number}（${hoursText(x.hours)}）`).join('、')}`\n        + (rest > 0 ? ` …其余 ${rest} 条见卡片` : ''),\n      );\n    } else {\n      lines.push('  ⏳ 没有超过上游中位数的 PR（都还在正常等待区间）');\n    }\n  }\n  const ordered = sortWorks(report.works);\n  const compact = ordered.length > COMPACT_THRESHOLD;\n  if (compact) {\n    lines.push(`  （作品 ${ordered.length} 个，超过 ${COMPACT_THRESHOLD} 个自动切紧凑视图：一行一个，需要盯的排前面）`);\n  }\n\n  for (const item of ordered) {\n    const { work, local, github, market, npm } = item;\n    const bits = [];\n    bits.push(local.available === true ? `本地 ${local.version ?? '?'} / ${local.files ?? '?'} 文件${local.hasSmoke ? ' / 有自测' : ''}` : `本地 **读不到**（${local.reason ?? '?'}）`);\n    bits.push(github.exists === true ? `GitHub star ${github.stars} / 最后推送 ${shortTime(github.pushedAt)}` : (github.exists === false ? 'GitHub **没有仓库**' : `GitHub **读不到**（${github.reason ?? '?'}）`));\n    if (market.listed === true) {\n      // 没下载数 ≠ 没发 npm：下载字段市场侧可能不统计。npm 发没发看下面那行 npm 事实，不在这里推。\n      bits.push(market.downloads === null || market.downloads === undefined\n        ? '市场 **已收录**（没有下载数据）'\n        : `市场 **已收录**（下载 ${market.downloads}${market.rankInCategory ? `，同类第 ${market.rankInCategory}/${market.categorySize}` : ''}）`);\n    } else if (market.available === true) {\n      bits.push('市场 **未收录**');\n    } else {\n      bits.push(`市场 **读不到**（${market.reason ?? '?'}）`);\n    }\n    if (npm?.published === true) bits.push(`npm 有包（${npm.version}）`);\n    else if (npm?.available === true) bits.push('npm 没有');\n\n    let prText = '';\n    if (github.pr) {\n      const waited = (Date.now() - Date.parse(github.pr.createdAt)) / 3600000;\n      if (github.pr.mergedAt) prText = `／PR #${github.pr.number} **已合并**`;\n      else if (github.pr.state === 'open') {\n        const median = report.upstream?.available === true ? `（上游中位数 ${hoursText(report.upstream.medianHours)}）` : '';\n        prText = `／PR #${github.pr.number} 待合并，已等 ${hoursText(waited)}${median}`;\n      } else prText = `／PR #${github.pr.number} ${github.pr.state}`;\n    } else {\n      prText = '／**没有市场 PR**';\n    }\n\n    if (compact) {\n      // 一行一个：名字（中文） · 版本 · star · 市场/PR 状态（详情与链接看卡片）\n      const dl = market.downloads === null || market.downloads === undefined ? '下载数暂无' : `${market.downloads}↓`;\n      const marketText = market.listed !== true\n        ? (market.available === true ? '未收录' : '市场读不到')\n        : (npm?.published === true ? `已收录 · ${dl}` : (npm?.available === true ? `已收录 · ${dl} · npm 未发` : `已收录 · ${dl}`));\n      const prShort = github.pr\n        ? (github.pr.mergedAt ? `#${github.pr.number} 已合并` : (github.pr.state === 'open' ? `#${github.pr.number} 等 ${hoursText((Date.now() - Date.parse(github.pr.createdAt)) / 3600000)}` : `#${github.pr.number} ${github.pr.state}`))\n        : '无 PR';\n      lines.push(`  · ${displayName(item)}｜v${local.version ?? '?'}｜star ${github.exists === true ? github.stars : '—'}｜${marketText}｜${prShort}`);\n      if (github.exists !== true) lines.push(`      ⚠ GitHub ${github.exists === false ? '没有仓库' : '读不到'}（${github.reason ?? '?'}）`);\n    } else {\n      lines.push(`  · ${displayName(item)}`);\n      lines.push(`      ${bits.join('｜')}${prText}`);\n      const link = item.links?.github;\n      if (link) lines.push(`      直达：${link}`);\n    }\n  }\n  lines.push('  卡片：见 htmlPath（可直接打开/截图）');\n  return lines.join('\\n');\n}\n\n/** 显示名：英文名 +（中文名）。中文名来自名册 nameZh，其次 package.json 的 dsh.displayName。 */\nfunction displayName(item) {\n  const zh = item?.work?.nameZh ?? item?.local?.displayName ?? null;\n  return zh ? `${item.work.name}（${zh}）` : item.work.name;\n}\n\n/** 一个状态点。 */\nfunction dot(kind) {\n  const color = { good: '#3fb950', warn: '#d29922', bad: '#f85149', idle: '#6e7681' }[kind] ?? '#6e7681';\n  return `<span class=\"dot\" style=\"background:${color}\"></span>`;\n}\n\n/**\n * 紧凑表格：作品多（> COMPACT_THRESHOLD）时用一屏多行的表格，而不是一作品一大卡。\n * @param {Array<object>} ordered 已排序的作品\n * @returns {string} HTML\n */\nfunction renderGrid(ordered) {\n  const rows = ordered.map((item) => {\n    const { work, local, github, market, npm } = item;\n    const key = urgencyOf(item);\n    const pr = github?.pr;\n    const prText = pr\n      ? (pr.mergedAt\n        ? `${dot('good')} #${pr.number} 已合并`\n        : (pr.state === 'open'\n          ? `${dot('warn')} #${pr.number} 等 ${hoursText((Date.now() - Date.parse(pr.createdAt)) / 3600000)}`\n          : `#${pr.number} ${esc(pr.state)}`))\n      : '<span class=\"bad\">没有 PR</span>';\n    const dlGrid = market.downloads === null || market.downloads === undefined ? '下载数暂无' : `${market.downloads}↓`;\n    const marketText = market.listed !== true\n      ? (market.available === true ? `${dot('warn')} 未收录` : '<span class=\"bad\">读不到</span>')\n      : (npm?.available === true && npm.published !== true\n        ? `${dot('warn')} 已收录 · ${dlGrid} · npm 未发`\n        : `${dot('good')} 已收录 · ${dlGrid}`);\n    const ghText = github.exists === true\n      ? `${dot('idle')} star ${github.stars}`\n      : (github.exists === false ? '<span class=\"bad\">仓库不存在</span>' : '<span class=\"bad\">读不到</span>');\n    const why = key.tier === 0 ? '<div class=\"why\">需要处理</div>' : '';\n    const link = item.links?.github ?? null;\n    const zh = work.nameZh ?? local.displayName ?? null;\n    const nameCell = link\n      ? `<a href=\"${esc(link)}\" target=\"_blank\" rel=\"noreferrer\">${esc(work.name)}</a>`\n      : esc(work.name);\n    return `<tr class=\"t${key.tier}\">\n      <td class=\"name\">${nameCell}${zh ? `<span class=\"zh\">${esc(zh)}</span>` : ''}${why}</td>\n      <td>${esc(work.category ?? '—')}</td>\n      <td class=\"num\">${esc(local.available === true ? local.version ?? '?' : '读不到')}</td>\n      <td>${ghText}</td>\n      <td>${marketText}</td>\n      <td class=\"num\">${prText}</td>\n    </tr>`;\n  }).join('\\n');\n\n  return `<table class=\"grid\">\n    <thead><tr><th>作品（需要处理的排前面）</th><th>分类</th><th>版本</th><th>GitHub</th><th>市场</th><th>收录 PR</th></tr></thead>\n    <tbody>\n${rows}\n    </tbody>\n  </table>`;\n}\n\n/**\n * 给人看的卡片（单文件 HTML）。\n * @param {object} report collectAll 的结果\n * @returns {string} HTML\n */\nexport function renderHtml(report) {\n  const s = report.summary;\n  const median = report.upstream?.available === true ? `上游中位数 ${hoursText(report.upstream.medianHours)}` : '上游节奏未知';\n  const ordered = sortWorks(report.works);\n  const compact = ordered.length > COMPACT_THRESHOLD;\n\n  const cards = ordered.map((item) => {\n    const { work, local, github, market, npm } = item;\n    const listed = market.listed === true;\n    const rows = [];\n\n    rows.push(`<div class=\"row\"><span class=\"k\">本地</span><span class=\"v\">${\n      local.available === true\n        ? `${esc(local.version ?? '?')} · ${local.files ?? '?'} 文件${local.hasSmoke ? ' · 有自测' : ''}`\n        : `<span class=\"bad\">读不到（${esc(local.reason ?? '')}）</span>`\n    }</span></div>`);\n\n    rows.push(`<div class=\"row\"><span class=\"k\">GitHub</span><span class=\"v\">${\n      github.exists === true\n        ? `${dot(github.stars > 0 ? 'good' : 'idle')} star ${github.stars} · fork ${github.forks} · 最后推送 ${shortTime(github.pushedAt)}`\n        : (github.exists === false ? '<span class=\"bad\">仓库不存在</span>' : `<span class=\"bad\">读不到（${esc(github.reason ?? '')}）</span>`)\n    }</span></div>`);\n\n    rows.push(`<div class=\"row\"><span class=\"k\">市场</span><span class=\"v\">${\n      listed\n        ? (market.downloads === null || market.downloads === undefined\n          ? `${dot('warn')} 已收录 · 下载数暂无`\n          : `${dot('good')} 已收录 · 下载 <b>${market.downloads}</b>${market.rankInCategory ? ` · 同类 ${market.rankInCategory}/${market.categorySize}` : ''}`)\n        : (market.available === true ? `${dot('warn')} 还没收录` : `<span class=\"bad\">读不到（${esc(market.reason ?? '')}）</span>`)\n    }</span></div>`);\n\n    let prHtml = `<div class=\"row\"><span class=\"k\">收录 PR</span><span class=\"v\"><span class=\"bad\">没有 PR</span></span></div>`;\n    if (github.pr) {\n      const waited = (Date.now() - Date.parse(github.pr.createdAt)) / 3600000;\n      if (github.pr.mergedAt) {\n        prHtml = `<div class=\"row\"><span class=\"k\">收录 PR</span><span class=\"v\">${dot('good')} #${github.pr.number} 已合并</span></div>`;\n      } else if (github.pr.state === 'open') {\n        prHtml = `<div class=\"row\"><span class=\"k\">收录 PR</span><span class=\"v\">${dot('warn')} #${github.pr.number} 待合并 · 已等 <b>${hoursText(waited)}</b><span class=\"muted\">（${esc(median)}）</span></span></div>`;\n      } else {\n        prHtml = `<div class=\"row\"><span class=\"k\">收录 PR</span><span class=\"v\">#${github.pr.number} ${esc(github.pr.state)}</span></div>`;\n      }\n    }\n    rows.push(prHtml);\n\n    if (npm?.published === true) {\n      rows.push(`<div class=\"row\"><span class=\"k\">npm</span><span class=\"v\">${dot('good')} 有包 ${esc(npm.version ?? '')}</span></div>`);\n    } else if (npm?.available === true) {\n      rows.push(`<div class=\"row\"><span class=\"k\">npm</span><span class=\"v\">${dot('warn')} registry 上没有这个包</span></div>`);\n    } else if (npm?.reason) {\n      rows.push(`<div class=\"row\"><span class=\"k\">npm</span><span class=\"v\">${dot('idle')} 没查到（${esc(npm.reason)}）</span></div>`);\n    }\n\n    const head = listed ? 'listed' : (github.exists === true ? 'shipped' : 'local');\n    const headText = listed ? '已上市场' : (github.exists === true ? '已发布 · 等收录' : '仅本地');\n    const link = item.links?.github ?? null;\n    const zh = work.nameZh ?? local.displayName ?? null;\n    const title = link\n      ? `<a href=\"${esc(link)}\" target=\"_blank\" rel=\"noreferrer\">${esc(work.name)}</a>`\n      : esc(work.name);\n\n    // 直达：GitHub / npm / 市场条目页（能确定才给，不编地址）\n    const linkBits = [];\n    if (link) linkBits.push(`<a href=\"${esc(link)}\" target=\"_blank\" rel=\"noreferrer\">GitHub</a>`);\n    if (npm?.available === true && item.links?.npm) linkBits.push(`<a href=\"${esc(item.links.npm)}\" target=\"_blank\" rel=\"noreferrer\">npm${npm.published === true ? '' : '（没有）'}</a>`);\n    if (item.links?.market) linkBits.push(`<a href=\"${esc(item.links.market)}\" target=\"_blank\" rel=\"noreferrer\">市场条目</a>`);\n    if (linkBits.length > 0) rows.push(`<div class=\"row\"><span class=\"k\">直达</span><span class=\"v\">${linkBits.join(' · ')}</span></div>`);\n\n    return `<section class=\"card ${head}\">\n      <header>\n        <h2>${title}${zh ? `<span class=\"zh\">${esc(zh)}</span>` : ''}</h2>\n        <span class=\"badge\">${esc(work.category ?? '—')}</span>\n        <span class=\"state\">${headText}</span>\n      </header>\n      ${rows.join('\\n      ')}\n    </section>`;\n  }).join('\\n    ');\n\n  return `<!doctype html>\n<html lang=\"zh\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>作品看板 · ${esc(report.owner)}</title>\n<style>\n  :root { color-scheme: dark; }\n  * { box-sizing: border-box; }\n  body { margin: 0; padding: 32px; background: #0d1117; color: #e6edf3;\n         font-family: \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif; }\n  .wrap { max-width: 980px; margin: 0 auto; }\n  h1 { font-size: 26px; margin: 0 0 4px; letter-spacing: .5px; }\n  .sub { color: #8b949e; font-size: 13px; margin-bottom: 22px; }\n  .tiles { display: grid; grid-template-columns: repeat(5, 1fr); gap: 12px; margin-bottom: 24px;\n           position: sticky; top: 0; z-index: 2; background: #0d1117; padding: 8px 0 12px; }\n  .tile { background: #161b22; border: 1px solid #21262d; border-radius: 12px; padding: 14px 16px; }\n  .tile .n { font-size: 26px; font-weight: 700; font-variant-numeric: tabular-nums; }\n  .tile .l { color: #8b949e; font-size: 12px; margin-top: 2px; }\n  .card { background: #161b22; border: 1px solid #21262d; border-left: 3px solid #6e7681;\n          border-radius: 12px; padding: 16px 18px; margin-bottom: 14px; }\n  .card.listed { border-left-color: #3fb950; }\n  .card.shipped { border-left-color: #d29922; }\n  .card header { display: flex; align-items: baseline; gap: 10px; margin-bottom: 10px; }\n  .card h2 { font-size: 17px; margin: 0; font-family: ui-monospace, Consolas, monospace; }\n  .card h2 a { color: inherit; text-decoration: none; border-bottom: 1px dashed #30363d; }\n  .card h2 a:hover { border-bottom-color: #58a6ff; color: #58a6ff; }\n  .zh { font-family: \"Microsoft YaHei\", system-ui, sans-serif; font-size: 13px; color: #8b949e; margin-left: 6px; }\n  .grid td.name a { color: inherit; text-decoration: none; border-bottom: 1px dashed #30363d; }\n  .grid td.name a:hover { border-bottom-color: #58a6ff; color: #58a6ff; }\n  .badge { font-size: 11px; color: #8b949e; border: 1px solid #30363d; border-radius: 999px; padding: 1px 8px; }\n  .state { margin-left: auto; font-size: 12px; color: #8b949e; }\n  .row { display: flex; gap: 10px; padding: 3px 0; font-size: 13px; line-height: 1.7; }\n  .k { color: #8b949e; width: 68px; flex: none; }\n  .v { font-variant-numeric: tabular-nums; }\n  .muted { color: #6e7681; }\n  .bad { color: #f85149; }\n  .dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 6px; }\n  .grid { width: 100%; border-collapse: collapse; font-size: 13px; }\n  .grid th { text-align: left; color: #8b949e; font-weight: 600; font-size: 12px;\n             padding: 8px 10px; border-bottom: 1px solid #30363d; position: sticky; top: 88px;\n             background: #0d1117; z-index: 1; }\n  .grid td { padding: 7px 10px; border-bottom: 1px solid #21262d; vertical-align: top; }\n  .grid tr:hover td { background: #161b22; }\n  .grid td.name { font-family: ui-monospace, Consolas, monospace; }\n  .grid tr.t0 td.name { border-left: 3px solid #f85149; padding-left: 7px; }\n  .grid tr.t1 td.name { border-left: 3px solid #d29922; padding-left: 7px; }\n  .grid tr.t2 td.name { border-left: 3px solid #3fb950; padding-left: 7px; }\n  .grid .num { font-variant-numeric: tabular-nums; }\n  .grid .why { color: #6e7681; font-size: 12px; }\n  footer { color: #6e7681; font-size: 12px; margin-top: 20px; line-height: 1.8; }\n</style>\n</head>\n<body>\n  <div class=\"wrap\">\n    <h1>🚢 作品看板</h1>\n    <div class=\"sub\">${esc(report.owner)} · 生成于 ${esc(shortTime(report.generatedAt))} · 登记表 ${esc(report.market.available === true ? `${report.market.count} 条（${report.market.updated ?? '?'}）` : '读不到')}</div>\n\n    <div class=\"tiles\">\n      <div class=\"tile\"><div class=\"n\">${s.works}</div><div class=\"l\">作品</div></div>\n      <div class=\"tile\"><div class=\"n\">${s.published}</div><div class=\"l\">已发布</div></div>\n      <div class=\"tile\"><div class=\"n\">${s.listed}</div><div class=\"l\">市场已收录</div></div>\n      <div class=\"tile\"><div class=\"n\">${s.totalDownloads}</div><div class=\"l\">总下载</div></div>\n      <div class=\"tile\"><div class=\"n\">${s.openPrs}</div><div class=\"l\">待合 PR</div></div>\n    </div>\n\n    ${compact ? renderGrid(ordered) : cards}\n\n    <footer>\n      上游 ${esc(report.upstream?.upstream ?? '?')}：${esc(median)}${report.upstream?.samples ? `（样本 ${report.upstream.samples}）` : ''}<br>\n      「市场已收录」= 市场登记表里能查到这个名字；「待合并」= 收录 PR 还开着。数字来自 GitHub API 与本机市场接口，**不经模型生成**。\n    </footer>\n  </div>\n</body>\n</html>\n`;\n}\n\n/**\n * 把报告落盘成卡片（可选同时落一份 JSON）。\n * @param {object} report 报告\n * @param {object} opts 选项 `{ dir, html, json, now }`\n * @returns {Promise<{htmlPath:string|null, jsonPath:string|null}>} 落盘结果\n */\nexport async function writeReport(report, { dir, html = true, json = false, now = Date.now() } = {}) {\n  const target = dir ?? join(process.env.USERPROFILE ?? process.env.HOME ?? '.', '.dsh', 'lighthouse-reports');\n  await mkdir(target, { recursive: true });\n  const stamp = new Date(now).toISOString().replace(/[:.]/g, '-').slice(0, 19);\n  const out = { htmlPath: null, jsonPath: null };\n  if (html) {\n    out.htmlPath = join(target, `lighthouse-${stamp}.html`);\n    await writeFile(out.htmlPath, renderHtml(report), 'utf8');\n  }\n  if (json) {\n    out.jsonPath = join(target, `lighthouse-${stamp}.json`);\n    await writeFile(out.jsonPath, JSON.stringify(report, null, 2), 'utf8');\n  }\n  return out;\n}\n"
